CREATE OR REPLACE FUNCTION public.icash_claim_email_before_cancellation(p_account uuid, p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare e public.icash_deal_emails;m public.icash_network_matches;b public.icash_network_buyers;c jsonb;result jsonb;
begin
 select * into e from public.icash_deal_emails where id=p_id and account_id=p_account;
 if e.contact_key like 'network:%' then
  select * into m from public.icash_network_matches where id::text=substring(e.contact_key from 9) and account_id=p_account and deal_id=e.deal_id;
  if not found then return null;end if;
  select * into b from public.icash_network_buyers where id=m.buyer_id for update;
  if not public.icash_network_match_current(m.id) then return null;end if;
  if m.email_id=e.id then
   c:=public.icash_network_email_content(m.id);
   if c is null or e.subject is distinct from c->>'subject' or e.body_text is distinct from c->>'body' then return null;end if;
   if (select count(*) from public.icash_network_matches nm join public.icash_deal_emails sent on sent.id=nm.email_id where nm.buyer_id=b.id and sent.id<>e.id and sent.updated_at>now()-interval '24 hours' and sent.state in ('dispatching','accepted','needs_review'))>=b.daily_emails then return null;end if;
  elsif m.state not in ('interested','replied') then return null;
  end if;
  if e.body_text ~* '(underlying purchase price|assignment fee)\s*:|includes the \$[0-9][0-9,.]* assignment fee' then return null;end if;
  result:=public.icash_claim_email_before_network(p_account,p_id);
  if result is not null then return result||jsonb_build_object('unsubscribeUrl','https://homeoffernetwork.com/buyers/unsubscribe/'||b.unsubscribe_token);end if;
  return null;
 end if;
 return public.icash_claim_email_before_network(p_account,p_id);
end $function$

CREATE OR REPLACE FUNCTION public.icash_claim_text_before_ai(p_account uuid, p_message uuid, p_sender text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare m public.icash_text_messages;t public.icash_text_threads;r uuid;h integer;prop text;
begin
 perform 1 from public.icash_operating_budget where id=1 for update;
 select * into m from public.icash_text_messages where id=p_message and account_id=p_account;
 select * into t from public.icash_text_threads where id=m.thread_id and account_id=p_account;
 if t.id is null then return null;end if;
 perform pg_advisory_xact_lock(hashtextextended(t.recipient,74));
 select * into m from public.icash_text_messages where id=p_message and account_id=p_account for update;
 if not found or m.state<>'ready' or m.direction<>'outgoing' then return null;end if;
 select * into t from public.icash_text_threads where id=m.thread_id and account_id=p_account for update;
 if not found or (t.paused and not (public.icash_manual_handoff_reply(p_account,t.id) and not exists(select 1 from public.icash_text_ai_jobs where outgoing_id=p_message and account_id=p_account))) or t.sender<>p_sender or not public.icash_sms_thread_review_current(p_account,t.id,true) then return null;end if;
 if not exists(select 1 from public.icash_text_senders where phone=t.sender and enabled) then return null;end if;
 if exists(select 1 from public.icash_text_suppressions where phone=t.recipient) then return null;end if;
 perform 1 from public.icash_accounts where id=p_account and not bot_paused for update;if not found then return null;end if;
 select s.snapshot->>'propertyId' into prop from public.icash_deal_files d join public.icash_screening_jobs s on s.id=d.screening_id and s.account_id=d.account_id where d.id=t.deal_id and d.account_id=p_account and d.stage not in ('cancelled','closed');
 if prop is null then return null;end if;
 h:=extract(hour from now() at time zone t.timezone);if (h<9 or h>=20) and not public.icash_seller_sms_permission_current(p_account,t.id,false) and not public.icash_seller_sms_inquiry_window(p_account,t.id) then return null;end if;
 -- Human-authored API sends; automated generation/queueing is not enabled by this RPC.
 if cardinality(m.asset_ids)>0 and (select count(*) from public.icash_text_assets where id=any(m.asset_ids) and account_id=p_account and deal_id=t.deal_id and verified_until>now())<>cardinality(m.asset_ids) then return null;end if;
 if cardinality(m.asset_ids)>0 and (select jsonb_agg(url order by id) from public.icash_text_assets where id=any(m.asset_ids)) is distinct from m.attachments then return null;end if;
 r:=case when cardinality(m.asset_ids)>0 then t.mms_rate_id else t.sms_rate_id end;
 if not exists(select 1 from public.icash_operation_rates where id=r and operation=case when cardinality(m.asset_ids)>0 then 'mms_send' else 'sms_send' end and enabled and expires_at>now()) then return null;end if;
 perform public.icash_reserve_operation(p_account,'text:'||m.id,r,public.icash_sms_thread_dispatch_until(p_account,t.id));
 if not public.icash_claim_operation('text:'||m.id) then raise exception 'Text already dispatched';end if;
 update public.icash_text_messages set state='dispatching',updated_at=now() where id=m.id;
 return jsonb_build_object('from',t.sender,'to',t.recipient,'message',m.body,'attachments',m.attachments);
end $function$

CREATE OR REPLACE FUNCTION public.icash_meta_claim_text(p_account uuid, p_message uuid, p_sender text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare msg public.icash_text_messages;t public.icash_text_threads;m public.icash_meta_leads;h integer;
begin
 perform 1 from public.icash_operating_budget where id=1 for update;
 select ml.* into m from public.icash_meta_lead_messages mm join public.icash_meta_leads ml on ml.lead_id=mm.lead_id where mm.message_id=p_message and ml.account_id=p_account for share of ml;
 if not found then return null;end if;

 if exists(select 1 from public.icash_meta_lead_messages mm where mm.message_id=p_message and mm.purpose in ('followup_1','followup_2')
  and not public.icash_meta_followup_current(mm.lead_id,mm.purpose)) then return null;end if;
if not public.icash_sms_message_route_current(p_account,p_message) then return null;end if;
 select * into msg from public.icash_text_messages where id=p_message and account_id=p_account for update;
 if not found or msg.state<>'ready' or msg.direction<>'outgoing' or cardinality(msg.asset_ids)>0 or msg.attachments<>'[]'::jsonb then return null;end if;
 select * into t from public.icash_text_threads where id=msg.thread_id and account_id=p_account for update;
 if not found or t.seller_intake_id is distinct from m.lead_id or t.sender<>p_sender or not public.icash_seller_sms_permission_current(p_account,t.id,false) then return null;end if;
 perform pg_advisory_xact_lock(hashtextextended(t.recipient,74));
 if m.paused or m.declined_at is not null or not exists(select 1 from public.icash_accounts where id=p_account and not bot_paused) then return null;end if;
 h:=extract(hour from now() at time zone t.timezone);
 -- Verified Meta contact evidence is checked above; no clock-hour gate.
 -- The normal reserve snapshots actual-cost pricing, membership, credits,
 -- explicit channel disables, billing reviews and uncertain-send protection.
 perform public.icash_reserve_operation(p_account,'text:'||msg.id,t.sms_rate_id,t.permission_until);
 if not public.icash_claim_operation('text:'||msg.id) then return null;end if;
 update public.icash_text_messages set state='dispatching',updated_at=now() where id=msg.id;
 return jsonb_build_object('from',t.sender,'to',t.recipient,'message',msg.body,'attachments',msg.attachments);
end $function$

CREATE OR REPLACE FUNCTION public.icash_next_before_closing_gaps()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare prior jsonb;g public.icash_seller_gaps;mid uuid;ticket public.icash_automation_tickets;f public.icash_seller_viewing_followups;
begin
 perform pg_advisory_xact_lock(726341927);
 update public.icash_seller_gaps set state='needs_review',updated_at=now() where state in ('open','queued','waiting') and expires_at<=now();
 prior:=public.icash_next_before_seller_recovery();if prior->>'token' is not null then return prior;end if;
 if not exists(select 1 from public.icash_operating_budget where id=1 and enabled) then return prior;end if;
 if exists(select 1 from public.icash_automation_tickets where kind='seller_recovery' and created_at>now()-interval '1 minute') then return prior;end if;
 for f in select followup.* from public.icash_seller_viewing_followups followup join public.icash_text_threads t on t.id=followup.buyer_thread_id and t.account_id=followup.account_id
  join public.icash_accounts a on a.id=followup.account_id and not a.bot_paused
  join public.icash_wallets w on w.account_id=a.id and w.balance_cents>0
  join pg_timezone_names tz on tz.name=t.timezone
  where followup.outgoing_id is null and followup.created_at>now()-interval '7 days' and extract(hour from now() at time zone tz.name) between 9 and 19
  order by followup.created_at for update of followup skip locked limit 20 loop
  mid:=public.icash_prepare_viewing_relay(f.request_id);
  if mid is not null then
   insert into public.icash_automation_tickets(account_id,kind,opener_message_id) values(f.account_id,'seller_recovery',mid) returning * into ticket;
   return jsonb_build_object('token',ticket.token);
  end if;
 end loop;
 for g in select gap.* from public.icash_seller_gaps gap join public.icash_text_threads t on t.id=gap.thread_id and t.account_id=gap.account_id
  join public.icash_accounts a on a.id=gap.account_id and not a.bot_paused
  join public.icash_wallets w on w.account_id=a.id and w.balance_cents>0
  join pg_timezone_names tz on tz.name=t.timezone
  where gap.state='open' and gap.due_at<=now() and gap.expires_at>now() and extract(hour from now() at time zone tz.name) between 9 and 19
  order by gap.due_at for update of gap skip locked limit 20 loop
  mid:=public.icash_prepare_seller_recovery(g.account_id,g.id);
  if mid is not null then
   insert into public.icash_automation_tickets(account_id,kind,opener_message_id) values(g.account_id,'seller_recovery',mid) returning * into ticket;
   return jsonb_build_object('token',ticket.token);
  end if;
  update public.icash_seller_gaps set due_at=now()+interval '1 hour',updated_at=now() where id=g.id and state='open';
 end loop;
 return prior;
end $function$

CREATE OR REPLACE FUNCTION public.icash_next_before_sms_inbound_campaign()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare prior jsonb;thread public.icash_text_threads;message uuid;ticket public.icash_automation_tickets;
begin
 perform pg_advisory_xact_lock(726341927);
 prior:=public.icash_next_before_seller_openers();
 if prior->>'token' is not null then return prior;end if;
 if not exists(select 1 from public.icash_operating_budget where id=1 and enabled) then return prior;end if;
 if exists(select 1 from public.icash_automation_tickets where kind='seller_opener' and created_at>now()-interval '1 minute') then return prior;end if;
 select t.* into thread from public.icash_text_threads t
 join public.icash_accounts a on a.id=t.account_id and not a.bot_paused
 join public.icash_wallets w on w.account_id=a.id and w.balance_cents>w.reserved_cents
 join public.icash_deal_files d on d.id=t.deal_id and d.account_id=t.account_id and d.stage='draft' and coalesce(d.terms->>'practice','false')<>'true'
 join public.icash_screening_jobs s on s.id=d.screening_id and s.account_id=t.account_id and s.state='complete' and s.result->'financialCheck'->>'status'='eligible' and s.completed_at>now()-interval '24 hours'
 join public.icash_timezone_names zone on zone.name=t.timezone
 where t.party='seller' and not t.paused and t.ai_mode='auto' and public.icash_sms_thread_dispatch_until(t.account_id,t.id)>now()
 and extract(hour from now() at time zone zone.name) between 9 and 19
 and not exists(select 1 from public.icash_text_messages m where m.thread_id=t.id)
 and not exists(select 1 from public.icash_text_suppressions x where x.phone=t.recipient)
 and not exists(select 1 from public.icash_property_controls pc where pc.account_id=a.id and pc.property_id=s.snapshot->>'propertyId' and pc.manual)
 order by t.id for update of t skip locked limit 1;
 if not found then return prior;end if;
 message:=public.icash_queue_seller_opener(thread.account_id,thread.id);
 if message is null then return prior;end if;
 insert into public.icash_automation_tickets(account_id,kind,opener_message_id) values(thread.account_id,'seller_opener',message) returning * into ticket;
 return jsonb_build_object('token',ticket.token);
end $function$

CREATE OR REPLACE FUNCTION public.icash_next_before_unstarted_sms_recovery()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare t public.icash_text_threads;m uuid;ticket public.icash_automation_tickets;
begin
 perform pg_advisory_xact_lock(726341927);
 if exists(select 1 from public.icash_operating_budget where id=1 and enabled) and not exists(select 1 from public.icash_automation_tickets where kind='seller_opener' and created_at>now()-interval '1 minute') then
 select th.* into t from public.icash_text_threads th join public.icash_accounts a on a.id=th.account_id and not a.bot_paused join public.icash_wallets w on w.account_id=a.id and w.balance_cents>w.reserved_cents join public.icash_deal_files d on d.id=th.deal_id and d.account_id=th.account_id and d.stage='draft' and coalesce(d.terms->>'practice','false')<>'true' join public.icash_screening_jobs sc on sc.id=d.screening_id and sc.account_id=d.account_id and sc.state='complete' and sc.result->'financialCheck'->>'status'='eligible' and sc.completed_at between now()-interval '24 hours' and now() join public.icash_timezone_names tz on tz.name=th.timezone
 where public.icash_outreach_sms_current(th.account_id) and not exists(select 1 from public.icash_property_controls pc where pc.account_id=th.account_id and pc.property_id=sc.snapshot->>'propertyId' and pc.manual) and th.party='seller' and not th.paused and th.ai_mode='auto' and public.icash_sms_thread_dispatch_until(th.account_id,th.id)>now() and extract(hour from now() at time zone tz.name) between 9 and 19 and not exists(select 1 from public.icash_text_suppressions s where s.phone=th.recipient)
 and (not exists(select 1 from public.icash_text_messages where thread_id=th.id) or exists(select 1 from public.icash_sms_inbound_invitations i join public.icash_text_messages msg on msg.id=i.message_id and msg.state='ready' where i.thread_id=th.id and i.expires_at>now() and not exists(select 1 from public.icash_automation_tickets old where old.opener_message_id=msg.id))) order by th.id for update of th skip locked limit 1;
 if found then
  select i.message_id into m from public.icash_sms_inbound_invitations i join public.icash_text_messages msg on msg.id=i.message_id and msg.state='ready' where i.thread_id=t.id and i.expires_at>now();
  if m is null then m:=public.icash_queue_seller_opener(t.account_id,t.id);end if;
  if m is not null then insert into public.icash_automation_tickets(account_id,kind,opener_message_id) values(t.account_id,'seller_opener',m) returning * into ticket;return jsonb_build_object('token',ticket.token);end if;
 end if;end if;
 return public.icash_next_before_sms_inbound_campaign();
end $function$

CREATE OR REPLACE FUNCTION public.icash_seller_sms_permission_current(p_account uuid, p_thread uuid, p_check_hour boolean DEFAULT true)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare t public.icash_text_threads;d public.icash_deal_files;r public.icash_operation_rates;e jsonb;price bigint;h integer;
begin
 select * into t from public.icash_text_threads where id=p_thread and account_id=p_account for share;
 if not found or t.seller_intake_id is null or t.party<>'seller' or t.paused or t.manual_only or t.ai_mode<>'auto'
  or t.dnc_clear or t.dnc_checked_at is not null or t.sms_review_request_id is not null or t.operational_contact_id is not null then return false;end if;
 select * into d from public.icash_deal_files where id=t.deal_id and account_id=p_account and stage not in ('closed','cancelled') and coalesce(terms->>'practice','false')<>'true' for share;
 if not found then return false;end if;
 e:=public.icash_seller_contact_evidence(p_account,d.screening_id,t.seller_intake_id,t.recipient);
 if e is null or t.permission_evidence is distinct from e->>'evidence' or t.timezone is distinct from e->>'timezone'
  or t.permission_until is distinct from (e->>'until')::timestamptz or not public.icash_outreach_sms_current(p_account) then return false;end if;
 perform 1 from public.icash_text_senders where phone=t.sender and enabled for share;
 if not found then return false;end if;
 select * into r from public.icash_operation_rates where id=t.sms_rate_id for share;
 if not found or not public.icash_sms_intake_rate_current(r.id)
  or encode(sha256(convert_to(to_jsonb(r)::text,'UTF8')),'hex') is distinct from t.seller_sms_rate_hash then return false;end if;
 select customer_micros into price from public.icash_communication_prices where operation='sms_segment' for share;
 if not found or price is null or t.seller_sms_price_micros is null or price>t.seller_sms_price_micros then return false;end if;
 if exists(select 1 from public.icash_property_controls pc join public.icash_screening_jobs s on s.account_id=pc.account_id and s.snapshot->>'propertyId'=pc.property_id where s.id=d.screening_id and s.account_id=p_account and pc.manual)
  or exists(select 1 from public.icash_handoffs where account_id=p_account and screening_id=d.screening_id and state<>'resolved') then return false;end if;
 h:=extract(hour from now() at time zone t.timezone);
 return true; -- All binding, consent and channel checks above still apply.
end $function$

CREATE OR REPLACE FUNCTION public.icash_sms_thread_review_current(p_account uuid, p_thread uuid, p_check_hour boolean DEFAULT true)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare x public.icash_owner_buyer_tests;
begin
 select * into x from public.icash_owner_buyer_tests where thread_id=p_thread;
 if found then
  return x.account_id=p_account and public.icash_owner_buyer_test_current(x.id) and exists(
   select 1 from public.icash_text_threads t where t.owner_buyer_test_id=x.id and t.id=x.thread_id and t.account_id=x.account_id and t.deal_id=x.deal_id
   and t.sender=x.sender and t.recipient=x.phone and t.party='buyer' and t.sms_rate_id=x.sms_rate_id
   and t.sender_pool_assigned and t.retired_at is null and not t.paused and not t.manual_only and t.ai_mode='auto'
   and t.seller_intake_id is null and t.operational_contact_id is null and t.sms_review_request_id is null);
 end if;
 return public.icash_sms_review_before_owner_buyer_test(p_account,p_thread,p_check_hour);
end $function$
